// MARK: - 翻译管理器

class I18nManager: ObservableObject {
    static let shared = I18nManager()

    @Published var currentLanguage: AppLanguage {
        didSet {
            UserDefaults.standard.set(currentLanguage.rawValue, forKey: "app_language")
            objectWillChange.send()
        }
    }

    private var translations: [AppLanguage: [String: String]] = [:]

    private static let i18nLog = Logger(subsystem: "com.fusion.studio", category: "I18n")

    init() {
        let saved = UserDefaults.standard.string(forKey: "app_language") ?? "zh-CN"
        currentLanguage = AppLanguage(rawValue: saved) ?? .zhCN
        loadTranslations()
    }

    // 审计0902 E6 (P2): 翻译数据从 25K 行内联 dict 拆为 Resources/i18n/*.json 外部资源。
    //   旧实现 4 个全局 [String:String] 内联致单 key 编辑触发全 25K 行重编。
    //   现 init/语言切换从 Bundle 加载 JSON; enUS 回退 + 缺失 key 落 raw 值 (t() 既有契约)。
    private func loadTranslations() {
        translations = [:]
        for lang in AppLanguage.allCases {
            // 审计0902 E6: SPM .process("Resources") 把 JSON 放进 package resource bundle (Bundle.module),
            //   非 Bundle.main。test runner 下 Bundle.main = xctest runner, 不含 module 资源 -> 旧查
            //   Bundle.main 致 testTranslation 全失败 (t() 落 raw key)。DesignCanvasView 同模式用 Bundle.module
            //   取 wasm/js, 此处对齐。先查 i18n/ 子目录 (process 保留), 再展平根, 最后 Bundle.main 兜底
            //   (app 打包后资源可能拷入 main bundle)。
            let url = Bundle.module.url(forResource: lang.jsonFileName, withExtension: "json", subdirectory: "i18n")
                ?? Bundle.module.url(forResource: lang.jsonFileName, withExtension: "json")
                ?? Bundle.main.url(forResource: lang.jsonFileName, withExtension: "json", subdirectory: "i18n")
                ?? Bundle.main.url(forResource: lang.jsonFileName, withExtension: "json")
            guard let url = url,
                  let data = try? Data(contentsOf: url),
                  let dict = try? JSONSerialization.jsonObject(with: data) as? [String: String] else {
                Self.i18nLog.error("loadTranslations: failed to load \(lang.jsonFileName).json — translations for this language unavailable")
                continue
            }
            translations[lang] = dict
            Self.i18nLog.info("loadTranslations: loaded \(lang.jsonFileName).json (\(dict.count) keys)")
        }
    }

    func t(_ key: I18nKey) -> String {
        translations[currentLanguage]?[key.rawValue] ?? translations[.enUS]?[key.rawValue] ?? key.rawValue
    }

    func t(_ key: String) -> String {
        translations[currentLanguage]?[key] ?? translations[.enUS]?[key] ?? key
    }

    func tf(_ key: I18nKey, _ args: CVarArg...) -> String {
        let format = t(key)
        return String(format: format, arguments: args)
    }
}

// MARK: - 国际化文本视图

struct I18nText: View {
    let key: I18nKey
    @StateObject private var i18n = I18nManager.shared

    init(_ key: I18nKey) { self.key = key }

    var body: some View {
        Text(i18n.t(key))
    }
}

struct I18nLabel: View {
    let key: I18nKey
    let icon: String
    @StateObject private var i18n = I18nManager.shared

    init(_ key: I18nKey, icon: String) { self.key = key; self.icon = icon }

    var body: some View {
        Label(i18n.t(key), systemImage: icon)
    }
}

// MARK: - 语言选择器

struct LanguagePickerView: View {
    @StateObject private var i18n = I18nManager.shared
    @State private var selectedLanguage: AppLanguage

    init() { _selectedLanguage = State(initialValue: I18nManager.shared.currentLanguage) }

    var body: some View {
        List {
            ForEach(AppLanguage.allCases) { lang in
                Button(action: {
                    selectedLanguage = lang
                    i18n.currentLanguage = lang
                }) {
                    HStack {
                        Text(lang.flag)
                            .font(.title)
                        VStack(alignment: .leading, spacing: 2) {
                            Text(lang.displayName)
                                .font(.headline)
                            Text(lang.localName)
                                .font(.subheadline)
                                .foregroundColor(.secondary)
                        }
                        Spacer()
                        if selectedLanguage == lang {
                            Image(systemName: "checkmark.circle.fill")
                                .foregroundColor(.accentColor)
                        }
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
            }
        }
        .navigationTitle("语言 / Language")
    }
}
